usage:
import { AuthMagicLink } from "@/components/design-for-ai/auth-magic-link";

<AuthMagicLink
  sender="login@halyard.app"
  expired={searchParams.get("error") === "expired"}
  onSend={async (email) => {
    const res = await fetch("/api/magic-link", { method: "POST", body: JSON.stringify({ email }) });
    if (!res.ok) throw new Error("We couldn’t send that email. Try again in a moment.");
  }}
/>
